/* Service worker: keeps the guide working offline. Generated by build_app.py. */
const CACHE = "npg-335622b3e86e";
const ASSETS = [
  "./",
  "./index.html",
  "./manifest.webmanifest",
  "./icons/icon-192.png",
  "./icons/icon-512.png",
  "./icons/maskable-512.png",
  "./icons/apple-touch-icon.png",
  "./icons/favicon-32.png",
  "./guides/Native_Plant_Cuttings_Guide_v1.5.pdf",
  "./guides/Native_Plant_Seed_Sowing_Guide_v1.5.pdf",
  "./guides/Native_Plant_Division_Guide_v1.1.pdf"
];

self.addEventListener("install", (event) => {
  event.waitUntil(caches.open(CACHE).then((cache) => cache.addAll(ASSETS)));
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    caches.keys()
      .then((keys) => Promise.all(keys.filter((k) => k.startsWith("npg-") && k !== CACHE).map((k) => caches.delete(k))))
      .then(() => self.clients.claim())
  );
});

self.addEventListener("message", (event) => {
  if (event.data && event.data.type === "SKIP_WAITING") self.skipWaiting();
});

self.addEventListener("fetch", (event) => {
  const req = event.request;
  if (req.method !== "GET") return;
  const url = new URL(req.url);
  if (url.origin !== self.location.origin) return;
  if (req.mode === "navigate") {
    const isPage = url.pathname.endsWith("/") || url.pathname.endsWith("/index.html");
    if (!isPage) {
      // e.g. a PDF guide: serve the file itself, never the app page
      event.respondWith(caches.match(req, { ignoreSearch: true }).then((hit) => hit || fetch(req)));
      return;
    }
    event.respondWith(
      caches.match("./index.html").then((hit) => hit || fetch(req)).catch(() => caches.match("./index.html"))
    );
    return;
  }
  event.respondWith(
    caches.match(req, { ignoreSearch: true }).then((hit) => hit || fetch(req).then((res) => {
      if (res.ok) { const copy = res.clone(); caches.open(CACHE).then((c) => c.put(req, copy)); }
      return res;
    }))
  );
});
